WITH RECURSIVE space_tree(id,space_name) AS (
SELECT id,space_name FROM BBX_PARK_SPACE


        sslc_code = #{sslcCode}


        AND id = #{spaceId}


        AND tenant_id = #{tenantId}


UNION ALL
SELECT s.id,s.space_name FROM BBX_PARK_SPACE s
INNER JOIN space_tree st ON s.parent_space_id = st.id
)
SELECT DISTINCT b.* FROM BBX_IOC_DEVICE b INNER JOIN space_tree st ON b.SPACE_ID = st.id
WHERE b.enable_status = 1 AND b.deleted = 1

    AND b.tenant_id = #{tenantId}

SELECT DISTINCT b.id,b.device_name,dg.id groupId,dg.group_code groupCode,dg.group_name groupName,eb.branch_name branchName
FROM BBX_IOC_DEVICE b
LEFT JOIN BBX_DEVICE_GROUP_REL dgr ON b.id = dgr.device_id AND dgr.tenant_id=#{tenantId}
LEFT JOIN BBX_DEVICE_GROUP dg ON dgr.group_id = dg.id AND dg.deleted = 1 AND dg.tenant_id=#{tenantId}
LEFT JOIN BBX_BRANCH_DEVICE bd ON b.id = bd.device_id AND bd.tenant_id=#{tenantId}
LEFT JOIN BBX_ENERGY_BRANCH eb ON bd.branch_id = eb.id AND eb.deleted = 1 AND eb.tenant_id=#{tenantId}
WHERE b.enable_status = 1 AND b.deleted = 1 AND b.tenant_id = #{tenantId}

    AND b.iot_device_platform IN

        #{platform}



    AND b.space_id = #{condition.spaceId}


    AND b.reading_type = #{condition.readingType}


    AND dg.id = #{condition.groupId}


    AND dg.group_code = #{condition.groupCode}


    AND b.device_name LIKE CONCAT('%', #{condition.deviceName}, '%')


    AND eb.id = #{condition.branchId}

WITH RECURSIVE space_tree(id,space_name) AS ( SELECT id,space_name FROM BBX_PARK_SPACE
sslc_code = #{sslcCode}
AND tenant_id = #{tenantId}
UNION ALL SELECT s.id,s.space_name FROM BBX_PARK_SPACE s INNER JOIN space_tree st ON s.parent_space_id = st.id ) SELECT COALESCE(d.department_id, 0) as deptId, COALESCE(d.department_name, '未分配部门') as deptName, COUNT(*) as deviceCount, ROUND(COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (), 2) as numRate FROM bbx_ioc_device d WHERE d.space_id IN (SELECT id FROM space_tree) AND d.deleted = 1 AND d.enable_status = 1
AND tenant_id = #{tenantId}
GROUP BY COALESCE(d.department_id, 0)

WITH RECURSIVE space_tree(id, parent_space_id, root_id, space_name) AS ( SELECT id, parent_space_id, id AS root_id, space_name FROM bbx_park_space WHERE deleted = 1 AND tenant_id = #{tenantId}
AND parent_space_id = #{spaceId}
AND parent_space_id = 0
UNION ALL SELECT s.id, s.parent_space_id, st.root_id, s.space_name FROM bbx_park_space s INNER JOIN space_tree st ON s.parent_space_id = st.id WHERE s.deleted = 1 AND s.tenant_id = #{tenantId} ) SELECT st.root_id AS spaceId, MAX(ps.space_name) AS spaceName, COUNT(DISTINCT d.id) AS deviceCount, CASE WHEN EXISTS ( SELECT 1 FROM bbx_park_space child WHERE child.parent_space_id = st.root_id AND child.deleted = 1 AND child.tenant_id = #{tenantId} ) THEN 1 ELSE 0 END AS hasChildren FROM space_tree st LEFT JOIN bbx_park_space ps ON st.root_id = ps.id LEFT JOIN BBX_IOC_DEVICE d ON st.id = d.space_id AND d.deleted = 1 AND d.ENABLE_STATUS = 1
AND d.IOT_DEVICE_PLATFORM != 0
GROUP BY st.root_id

WITH RECURSIVE space_tree(id, space_name) AS ( SELECT id, space_name FROM bbx_park_space
sslc_code = #{condition.sslcCode}
AND tenant_id = #{tenantId}
UNION ALL SELECT s.id, s.space_name FROM bbx_park_space s INNER JOIN space_tree st ON s.parent_space_id = st.id ), group_tree(id, group_parent_id, root_id, group_name) AS ( -- 获取直接子分组（根分组或指定分组下的子分组） SELECT id, group_parent_id, id AS root_id, group_name FROM BBX_DEVICE_GROUP
group_parent_id = #{condition.groupId}
group_parent_id =0 -- 未传入groupId时展示根级分组
AND tenant_id = #{tenantId}
UNION ALL -- 递归获取所有后代分组（用于统计告警数量） SELECT dg.id, dg.group_parent_id, gt.root_id, dg.group_name FROM BBX_DEVICE_GROUP dg INNER JOIN group_tree gt ON dg.group_parent_id = gt.id
AND dg.tenant_id = #{tenantId}
) SELECT gt.root_id AS id, MAX(dg.group_name) AS name, 'group' AS type, COUNT(DISTINCT a.id) AS alarmCount FROM group_tree gt LEFT JOIN BBX_DEVICE_GROUP dg ON gt.root_id = dg.id LEFT JOIN BBX_DEVICE_GROUP_REL dgr ON gt.id = dgr.group_id LEFT JOIN BBX_ALARM_DEVICE ad ON dgr.DEVICE_ID = ad.device_id LEFT JOIN BBX_ALARM_INFO a ON ad.alarm_id = a.id AND a.alarm_status != 3 LEFT JOIN BBX_IOC_DEVICE d ON dgr.device_id = d.id AND d.SPACE_ID IN (SELECT id FROM space_tree) GROUP BY gt.root_id ORDER BY gt.root_id

WITH RECURSIVE space_tree(id) AS ( SELECT id FROM bbx_park_space
sslc_code = #{condition.sslcCode}
AND tenant_id = #{tenantId}
UNION ALL SELECT s.id FROM bbx_park_space s INNER JOIN space_tree st ON s.parent_space_id = st.id ) SELECT d.id as device_id, d.device_name as name, 'device' as type, COUNT(DISTINCT a.id) as alarmCount FROM BBX_DEVICE_GROUP_REL dgr INNER JOIN BBX_IOC_DEVICE d ON dgr.DEVICE_ID = d.id AND d.SPACE_ID IN (SELECT id FROM space_tree) LEFT JOIN BBX_ALARM_DEVICE ad ON d.id = ad.device_id LEFT JOIN BBX_ALARM_INFO a ON ad.alarm_id = a.id AND a.alarm_status != 3 WHERE d.id IS NOT NULL
AND dgr.group_id = #{condition.groupId}
GROUP BY d.id, d.device_name

