UPDATE bbx_ioc_device SET reading_value = CASE id
WHEN #{device.id} THEN #{device.readingValue}
ELSE reading_value END, reading_time = CASE id
WHEN #{device.id} THEN #{device.readingTime}
ELSE reading_time END, reading_img = CASE id
WHEN #{device.id} THEN #{device.readingImg}
ELSE reading_img END WHERE id IN
#{device.id}
